#!/usr/bin/env bash
# record_all.sh -- record the claim-01..03 mutant witnesses (generated by gen_mutants.py).
# Run from anywhere; works in the bundle root. Every prover use holds one VM prover
# slot (the slot wraps the ledger call, as WS-H's run-controls.sh does); every
# invocation is a ledger event in provenance/ledger.jsonl.
#   concrete witnesses : mutant_witness.py record --kind concrete_trace_violation (2 replays)
#   symbolic witnesses : one trial replay, classified by the verifier's own judge
#                        (tcgverify.checkers.classify_kprove); then record with THAT kind
#                        (refute if the judge says refute, otherwise not_accept).
# Usage: record_all.sh [witness-name ...]   (default: all eight)
set -uo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BUNDLE="$(cd "$HERE/../.." && pwd)"
TOOLS="$(cd "$BUNDLE/../tools" && pwd)"
SLOT="${PILOT_SLOT:-$HOME/pilot-locks/with-slot.sh}"
cd "$BUNDLE"
names=("$@")
[[ ${#names[@]} -gt 0 ]] || names=(claim-01 claim-01-mask claim-02 claim-03
                                    claim-01-symbolic claim-01-mask-symbolic claim-02-symbolic claim-03-symbolic)
L() { "$SLOT" prover -- python3 "$TOOLS/ledger.py" run --ledger provenance/ledger.jsonl --root . "$@"; }
fail=0
for n in "${names[@]}"; do
  d="evidence/mutants/$n"
  claim="$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["claim"])' "$d/mutation.json")"
  ins=(); for f in "$d"/*.bin "$d"/*.k "$d"/replay.sh "$d"/mutation.json; do ins+=(--in "$f"); done
  if [[ "$n" == *-symbolic ]]; then
    echo "[mutants] $n: trial replay" >&2
    L --tool replay-sh --tool-hash "sha256:$(sha256sum "$d/replay.sh" | cut -c1-64)" "${ins[@]}" \
      --stdout "evidence/mutants/$n.trial.out" --stderr "evidence/mutants/$n.trial.err" \
      -- sh -c "cd $d && sh replay.sh"
    rc=$?
    verdict="$(python3 -I -c '
import sys; sys.path.insert(0, sys.argv[1])
from tcgverify import checkers
print(checkers.classify_kprove(int(sys.argv[2]), open(sys.argv[3], errors="replace").read(), False))' \
      "$TOOLS/../verifier" "$rc" "evidence/mutants/$n.trial.out")"
    kind=not_accept; [[ "$verdict" == refute ]] && kind=refute
    echo "[mutants] $n: trial exit $rc, judge says $verdict -> record as $kind" >&2
  else
    kind=concrete_trace_violation
  fi
  echo "[mutants] $n: record --kind $kind" >&2
  L --tool mutant-witness-record --tool-file "$TOOLS/mutant_witness.py" "${ins[@]}" \
    --out "$d/refutation.json" --stdout "evidence/mutants/$n.record.out" --stderr "evidence/mutants/$n.record.err" \
    -- python3 "$TOOLS/mutant_witness.py" record . "$n" --claim "$claim" --kind "$kind"
  rc=$?
  echo "[mutants] $n: record exit $rc: $(cat "evidence/mutants/$n.record.out")" >&2
  [[ $rc -eq 0 ]] || fail=1
done
exit $fail
